import fs from 'node:fs';
import assert from 'node:assert/strict';
const html = fs.readFileSync('mapa/index.html','utf8');
const runtime = fs.readFileSync('assets/js/features/mapa/controls.js','utf8');
const workspace = fs.readFileSync('assets/js/features/mapa/workspace.js','utf8');
const app = fs.readFileSync('assets/js/features/mapa/app.js','utf8');
const css = fs.readFileSync('assets/css/features/mapa/app.css','utf8');
assert.match(html,/id="gpsPointCoords"/);
assert.match(html,/id="gpsAddPointBtn"/);
assert.match(html,/id="gpsAdditionalPoints"/);
assert.match(html,/id="gpsCreatePolygonBtn"/);
assert.match(runtime,/createAdditionalPointRow/);
assert.match(runtime,/validPanelPoints/);
assert.match(runtime,/points\.length < 3/);
assert.match(runtime,/createPolygonFromPanelPoints/);
assert.match(runtime,/surveyor:gps-panel-visibility/);
assert.match(workspace,/carWfsCandidateUrls/);
assert.equal(workspace.includes('findCarInLocalMunicipality'), false);
assert.match(workspace,/maxFeatures: '2'/);
assert.match(workspace,/setTransientToolbarActive/);
assert.match(workspace,/sv-tool-active/);
assert.match(app,/buildSicarPropertyBoundaryLayer/);
assert.match(app,/sicar:sicar_imoveis_ba/);
assert.match(app,/https:\/\/geoserver\.car\.gov\.br\/geoserver\/sicar\/wms/);
assert.match(css,/gps-polygon-suggestion/);
assert.match(css,/surveyor-sicar-property-tile/);
console.log('OK: pontos múltiplos, toolbar ativa, busca CAR protegida e Limites de Propriedade via SICAR direto.');
